function Greeting({ name = 'friend', excited }) {
  return (
    <p>
      Hello, {name}
      {excited && '!'}
    </p>
  );
}

function Counter() {
  const [count, setCount] = useState(0);
  function handleClick() {
    setCount(count + 1);
    setCount(count + 1);
    setCount(count + 1);
  }
  return <button onClick={handleClick}>{count}</button>;
}

